1251				}
1252				else
1253				{
1254					handle_to_joyshock[handle] = make_shared<JoyShock>(handle, type);
1255				}
1256			}
1257		}
1258	
1259		if (numConnected == 1)
1260		{
1261			COUT << "1 device connected\n";
1262		}
1263		else if (numConnected == 0)
1264		{
1265			CERR << numConnected << " devices connected\n";

