345	void joyShockPollCallback(int jcHandle, JOY_SHOCK_STATE state, JOY_SHOCK_STATE lastState, IMU_STATE imuState, IMU_STATE lastImuState, float deltaTime)
346	{
347	
348		shared_ptr<JoyShock> jc = handle_to_joyshock[jcHandle];
349		if (jc == nullptr)
350			return;
351		jc->_context->callback_lock.lock();
352	
353		auto timeNow = chrono::steady_clock::now();
354		deltaTime = ((float)chrono::duration_cast<chrono::microseconds>(timeNow - jc->_timeNow).count()) / 1000000.0f;
355		jc->_timeNow = timeNow;
356	
357		if (triggerCalibrationStep)
358		{
359			calibrateTriggers(jc);
360			jc->_context->callback_lock.unlock();
361			return;
362		}
363	
364		MotionIf &motion = *jc->_motion;
365	
366		IMU_STATE imu = jsl->GetIMUState(jc->_handle);
367	
368		if (SettingsManager::getV<Switch>(SettingID::AUTO_CALIBRATE_GYRO)->value() == Switch::ON)
369		{
370			motion.SetAutoCalibration(true, 1.2f, 0.015f);
371		}
372		else
373		{
374			motion.SetAutoCalibration(false, 0.f, 0.f);
375		}
376		motion.ProcessMotion(imu.gyroX, imu.gyroY, imu.gyroZ, imu.accelX, imu.accelY, imu.accelZ, deltaTime);
377	
378		float inGyroX, inGyroY, inGyroZ;
379		motion.GetCalibratedGyro(inGyroX, inGyroY, inGyroZ);
380

