 32	// JSMVariable is a wrapper class for an underlying variable of type T.
 33	// This class allows other parts of the code be notified of when it changes value.
 34	// It also has a default value defined at construction that can be assigned on reset.
 35	// Finally it has a customizable filter function, to restrict possible values.
 36	// Setter functions return the object itself so they can be chained.
 37	template<typename T>
 38	class JSMVariable : public JSMVariableBase
 39	{
 40	public:
 41		// A listener function receives the new value as parameter.
 42		typedef function<void(const T &newVal)> OnChangeDelegate;
 43	
 44		// A filter function needs to return the value to be assigned.
 45		// It is given the current value and the next value that wishes to be assigned.
 46		typedef function<T(T current, T next)> FilterDelegate;
 47	
 48	protected:
 49		// The variable value itself
 50		T _value;
 51	
 52		// Parts of the code can be notified of when _value changes.
 53		map<unsigned int, OnChangeDelegate> _onChangeListeners;
 54	
 55		// The filtering function of the variable.
 56		FilterDelegate _filter;
 57	
 58		// The default filtering function simply accepts the new value.
 59		static T noFiltering(T old, T nu)
 60		{
 61			return nu;
 62		}
 63	
 64		// Default value of the variable. Cannot be changed after construction.
 65		const T _defVal;
 66	public:
 67	
 68		JSMVariable(T defaultValue = T())
 69		  : _value(defaultValue)
 70		  , _onChangeListeners()
 71		  , _filter(&noFiltering) // _filter is always valid
 72		  , _defVal(defaultValue)
 73		{
 74		}
 75	
 76		// Make a copy with a different default value
 77		JSMVariable(const JSMVariable &copy, T defaultValue)
 78		  : _value(defaultValue)
 79		  , _onChangeListeners() // Don't copy listeners. This is a different variable!
 80		  , _filter(copy._filter)
 81		  , _defVal(defaultValue)
 82		{
 83		}
 84	
 85		virtual ~JSMVariable()
 86		{
 87			_onChangeListeners.clear();
 88		}
 89	
 90		// Sets the filtering function for this variable. Also applies
 91		// the filter to it's current value.
 92		virtual JSMVariable *setFilter(FilterDelegate filterfunction)
 93		{
 94			_filter = filterfunction;
 95			set(_value); // Run the new filter on current value.
 96			return this;
 97		}
 98	
 99		// Remember to call this listener when the value changes.
100		virtual unsigned int addOnChangeListener(OnChangeDelegate listener, bool callListener = false)
101		{
102			_onChangeListeners[_delegateID] = listener;
103			if (callListener)
104			{
105				_onChangeListeners[_delegateID](_value);
106			}
107			return _delegateID++;
108		}
109	
110		// Remove the listener from list
111		virtual bool removeOnChangeListener(unsigned int id)
112		{
113			auto found = _onChangeListeners.find(id);
114			if (found != _onChangeListeners.end())
115			{
116				_onChangeListeners.erase(found);
117				return true;
118			}
119			return false;
120		}
121	
122		// reset the variable by assigning it its default value.
123		JSMVariable *reset() override
124		{
125			// Use operator to enable notification
126			set(_defVal);
127			return this;
128		}
129	
130		// Value can be read by implicit or explicit casting
131		// This enables easy usage of the variable within an operation.
132		virtual operator T() const
133		{
134			return _value;
135		}
136	
137		virtual const T &value() const
138		{
139			return _value;
140		}
141	
142		const T &defaultValue() const
143		{
144			return _defVal;
145		}
146	
147		// Value can be written by using set()
148		// N.B.: It's important to always use either function
149		// for changing the member _value
150		virtual T set(T newValue)
151		{
152			T oldValue = _value;
153			_value = _filter(oldValue, newValue); // Pass new value through filtering
154			if (_value != oldValue)
155			{
156				// Notify listeners of the change if there's a change
157				for (auto listener : _onChangeListeners)
158					listener.second(_value);
159			}
160			return _value; // Return actual value assign. Can be different from newValue because of filtering.
161		}
162	};
