164	// A chorded variable alternate values depending on _buttons enabling the chorded value
165	template<typename T>
166	class ChordedVariable : public JSMVariable<T>
167	{
168		using Base = JSMVariable<T>;
169	
170	protected:
171		// Each chord is a separate variable with its own listeners, but will use the same filtering and parsing.
172		map<ButtonID, JSMVariable<T>> _chordedVariables;
173	
174	public:
175		ChordedVariable(T defval)
176		  : Base(defval)
177		  , _chordedVariables()
178		{
179		}
180	
181		// Get the chorded variable, creating one if required.
182		JSMVariable<T> *atChord(ButtonID chord)
183		{
184			auto existingChord = _chordedVariables.find(chord);
185			if (existingChord == _chordedVariables.end())
186			{
187				// Create the chord when requested, using the copy constructor.
188				_chordedVariables.emplace(chord, JSMVariable<T>(*this, Base::_defVal));
189			}
190			return &_chordedVariables[chord];
191		}
192	
193		const JSMVariable<T> *atChord(ButtonID chord) const
194		{
195			auto existingChord = _chordedVariables.find(chord);
196			return existingChord != _chordedVariables.end() ? &existingChord->second : nullptr;
197		}
198	
199		// Obtain the value with provided chord if any.
200		optional<T> chordedValue(ButtonID chord) const
201		{
202			if (chord > ButtonID::NONE)
203			{
204				auto existingChord = _chordedVariables.find(chord);
205				return existingChord != _chordedVariables.end() ? optional<T>(T(existingChord->second)) : nullopt;
206			}
207			return chord != ButtonID::INVALID ? optional(Base::_value) : nullopt;
208		}
209		virtual operator T() const
210		{
211			return Base::value();
212		}
213	
214		virtual const T &value() const
215		{
216			return Base::value();
217		}
218	
219		// Resetting a chorded var always clears all chords.
220		virtual ChordedVariable<T> *reset() override
221		{
222			JSMVariable<T>::reset();
223			_chordedVariables.clear();
224			return this;
225		}
226	};
