 63	bool CmdRegistry::loadConfigFile(string fileName)
 64	{
 65		// https://stackoverflow.com/questions/2602013/read-whole-ascii-file-into-c-stdstring
 66		auto comment = fileName.find_first_of('#');
 67		if (comment != string::npos)
 68		{
 69			fileName = fileName.substr(0, comment - 1);
 70		}
 71		// Trim away quotation marks from drag and drop
 72		if (*fileName.begin() == '\"' && *(fileName.end() - 1) == '\"')
 73			fileName = fileName.substr(1, fileName.size() - 2);
 74	
 75		ifstream file(fileName);
 76		if (!file.is_open())
 77		{
 78			file.open(string{ BASE_JSM_CONFIG_FOLDER() } + fileName);
 79		}
 80		if (file)
 81		{
 82			COUT << "Loading commands from file ";
 83			COUT_INFO << fileName << '\n';
 84			// https://stackoverflow.com/questions/6892754/creating-a-simple-configuration-file-and-parser-in-c
 85			string line;
 86			while (getline(file, line))
 87			{
 88				processLine(line);
 89			}
 90			file.close();
 91			return true;
 92		}
 93		return false;
 94	}
