 96	string_view CmdRegistry::strtrim(string_view str)
 97	{
 98		if (str.empty())
 99			return {};
100	
101		while (isspace(str[0]))
102		{
103			str.remove_prefix(1);
104			if (str.empty())
105				return {};
106		}
107	
108		while (isspace(str.back()))
109		{
110			str.remove_suffix(1);
111			if (str.empty())
112				return {};
113		}
114	
115		return str;
116	}
