118	// Add a command to the registry. The regisrty takes ownership of the memory of this pointer.
119	// You can use _ASSERT() on the return value of this function to make sure the commands are
120	// accepted.
121	bool CmdRegistry::add(JSMCommand* newCommand)
122	{
123		// Check that the pointer is valid, that the name is valid.
124		if (newCommand && regex_match(newCommand->_name, regex(R"(^(\+|-|\w+)$)")))
125		{
126			// Unique pointers automatically delete the pointer on object destruction
127			_registry.emplace(newCommand->_name, unique_ptr<JSMCommand>(newCommand));
128			return true;
129		}
130		delete newCommand;
131		return false;
132	}
133	
134	bool CmdRegistry::Remove(string_view name)
135	{
136		// If I allow multiple commands with the same name, I should have a way to specify which one I want to remove.
137		CmdMap::iterator cmd = find_if(_registry.begin(), _registry.end(), bind(&CmdRegistry::findCommandWithName, name, placeholders::_1));
138		if (cmd != _registry.end())
139		{
140			_registry.erase(cmd);
141			return true;
142		}
143		return false;
144	}
145	
146	bool CmdRegistry::findCommandWithName(string_view name, const CmdMap::value_type& pair)
147	{
148		return name == pair.first;
149	}
