151	bool CmdRegistry::isCommandValid(string_view line) const
152	{
153		ifstream file(line.data());
154		if (file.is_open())
155		{
156			file.close();
157			return true;
158		}
159		smatch results;
160		string combo, name, arguments, label;
161		char op = '\0';
162		const string lineStr(line);
163		if (regex_match(lineStr, results, regex(R"(^\s*([+-]?\w*)\s*([,+]\s*([+-]?\w*))?\s*([^#\n]*)(#\s*(.*))?$)")))
164		{
165			if (results[2].length() > 0)
166			{
167				combo = results[1];
168				op = results[2].str()[0];
169				name = results[3];
170			}

