 42	bool JSMCommand::parseData(string_view arguments, string_view label)
 43	{
 44		_ASSERT_EXPR(_parse, L"There is no function defined to parse this command.");
 45		if (arguments.compare("HELP") == 0)
 46		{
 47			// Parsing has failed. Show help.
 48			COUT << _help << '\n';
 49		}
 50		else if (!_parse(this, arguments, label))
