103	{
104		// COUT << button._id << " processes event " << evt << '\n';
105		auto entry = _eventMapping.find(evt);
106		if (entry != _eventMapping.end() && entry->second) // Skip over empty entries
107		{
108			switch (evt)
109			{
110			case BtnEvent::OnPress:
111				COUT << button.getDisplayName() << ": true\n";
112				break;
113			case BtnEvent::OnRelease:
114			case BtnEvent::OnHoldRelease:
115				COUT << button.getDisplayName() << ": false\n";
116				break;
