146	bool Mapping::AddMapping(KeyCode key, EventModifier evtMod, ActionModifier actMod)
147	{
148		EventActionIf::Callback apply, apply2, release;
149		if (key.code == 0)
150		{
151			return false;
152		}
153		if (key.code == CALIBRATE)
154		{
155			apply = bind(&EventActionIf::StartCalibration, placeholders::_1);
156			release = bind(&EventActionIf::FinishCalibration, placeholders::_1);
157			_tapDurationMs = MAGIC_EXTENDED_TAP_DURATION; // Unused in regular press
158		}
159		else if (key.code >= GYRO_INV_X && key.code <= GYRO_TRACKBALL)
160		{
161			apply = bind(&EventActionIf::ApplyGyroAction, placeholders::_1, key);
162			release = bind(&EventActionIf::RemoveGyroAction, placeholders::_1);
163			_tapDurationMs = MAGIC_EXTENDED_TAP_DURATION; // Unused in regular press
164		}
165		else if (key.code == COMMAND_ACTION)
166		{
167			_ASSERT_EXPR(Mapping::_isCommandValid, "You need to assign a function to this field. It should be a function that validates the command line.");
168			if (!Mapping::_isCommandValid(key.name))
169			{
170				COUT << "Error: \"" << key.name << "\" is not a valid command\n";
171				return false;
172			}
173			apply = bind(&WriteToConsole, key.name);
174			release = EventActionIf::Callback();
175		}
176		else if (key.code == RUMBLE)
177		{
178			union Rumble
179			{
180				int raw;

