 14	istream &operator>>(istream &in, Mapping &mapping)
 15	{
 16		// Has friend access
 17		string valueName(128, '\0');
 18		in.getline(&valueName[0], valueName.size());
 19		valueName.resize(strlen(valueName.c_str()));
 20		smatch results;
 21		int count = 0;
 22	
 23		mapping._command = valueName;
 24		static constexpr string_view rgx = R"(\s*([!\^-]?)((\".*?\")|\w*[0-9A-Z]|\W)([\\\/+'_]?)\s*(.*))";
 25		while (regex_match(valueName, results, regex(rgx.data())) && !results[0].str().empty())
 26		{
 27			Mapping::ActionModifier actMod =
 28			  results[1].str().empty()   ? Mapping::ActionModifier::None :
 29			  results[1].str()[0] == '!' ? Mapping::ActionModifier::Instant :
 30			  results[1].str()[0] == '^' ? Mapping::ActionModifier::Toggle :
 31			  results[1].str()[0] == '-' ? Mapping::ActionModifier::Release :
 32			                               Mapping::ActionModifier::INVALID;
 33	
 34			string keyStr(results[2]);
 35	
 36			Mapping::EventModifier evtMod =
 37			  results[4].str().empty()    ? Mapping::EventModifier::Auto :
 38			  results[4].str()[0] == '\\' ? Mapping::EventModifier::StartPress :
 39			  results[4].str()[0] == '+'  ? Mapping::EventModifier::TurboPress :
 40			  results[4].str()[0] == '/'  ? Mapping::EventModifier::ReleasePress :
 41			  results[4].str()[0] == '\'' ? Mapping::EventModifier::TapPress :
 42			  results[4].str()[0] == '_'  ? Mapping::EventModifier::HoldPress :
 43			                                Mapping::EventModifier::INVALID;
 44	
 45			string leftovers(results[5]);
 46	
 47			KeyCode key(keyStr);
 48			if (evtMod == Mapping::EventModifier::Auto)
 49			{
 50				evtMod = count == 0 ? (leftovers.empty() ? Mapping::EventModifier::StartPress : Mapping::EventModifier::TapPress) :
 51				                      (count == 1 ? Mapping::EventModifier::HoldPress : Mapping::EventModifier::Auto);
 52			}
 53	
 54			// Some exceptions :(
 55			if (key.code == COMMAND_ACTION && actMod == Mapping::ActionModifier::None)
 56			{
 57				// Any command actions are instant by default
 58				actMod = Mapping::ActionModifier::Instant;
 59			}
 60			else if (key.code == CALIBRATE && actMod == Mapping::ActionModifier::None &&
 61			  (evtMod == Mapping::EventModifier::TapPress || evtMod == Mapping::EventModifier::ReleasePress))
 62			{
 63				// Calibrate only makes sense on tap or release if it toggles. Also preserves legacy.
 64				actMod = Mapping::ActionModifier::Toggle;
 65			}
 66	
 67			if (key.code == 0 ||
 68			  key.code == COMMAND_ACTION && actMod != Mapping::ActionModifier::Instant ||
 69			  actMod == Mapping::ActionModifier::INVALID ||
 70			  evtMod == Mapping::EventModifier::INVALID ||
 71			  evtMod == Mapping::EventModifier::Auto && count >= 2 ||
 72			  evtMod == Mapping::EventModifier::ReleasePress && actMod == Mapping::ActionModifier::None ||
 73			  !mapping.AddMapping(key, evtMod, actMod))
 74			{
 75				// error!!!
 76				in.setstate(in.failbit);
 77				break;
 78			}
 79			valueName = leftovers;
 80			count++;
 81		} // Next item
 82	
 83		return in;
 84	}
