 15	void ScrollAxis::processScroll(float distance, float sens, chrono::steady_clock::time_point now)
 16	{
 17		if (!_negativeButton || !_positiveButton)
 18			return; // not initalized!
 19	
 20		_leftovers += distance;
 21		//if (distance != 0)
 22		//	DEBUG_LOG << " leftover is now " << _leftovers << '\n';
 23		//"[" << _negativeId << "," << _positiveId << "] moved " << distance << " so that
 24	
 25		Pressed isPressed;
 26		isPressed.time_now = now;
 27		isPressed.turboTime = 50;
 28		isPressed.holdTime = 150;
 29		Released isReleased;
 30		isReleased.time_now = now;
 31		isReleased.turboTime = 50;
 32		isReleased.holdTime = 150;
 33		if (_pressedBtn != ButtonID::NONE)
 34		{
 35			float pressedTime = 0;
 36			if (_pressedBtn == _negativeButton->_id)
 37			{
 38				GetDuration dur{ now };
 39				pressedTime = _negativeButton->sendEvent(dur).out_duration;
 40				if (pressedTime < MAGIC_TAP_DURATION)
 41				{
 42					_negativeButton->sendEvent(isPressed);
 43					_positiveButton->sendEvent(isReleased);
 44					return;
 45				}
 46			}
 47			else // _pressedBtn == _positiveButton->_id
 48			{
 49				GetDuration dur{ now };
 50				pressedTime = _positiveButton->sendEvent(dur).out_duration;
 51				if (pressedTime < MAGIC_TAP_DURATION)
 52				{
 53					_negativeButton->sendEvent(isReleased);
 54					_positiveButton->sendEvent(isPressed);
 55					return;
 56				}
 57			}
 58			// pressed time > TAP_DURATION meaning release the tap
 59			_negativeButton->sendEvent(isReleased);
 60			_positiveButton->sendEvent(isReleased);
 61			_pressedBtn = ButtonID::NONE;
 62		}
 63		else if (fabsf(_leftovers) > sens)
 64		{
 65			if (_leftovers > 0)
 66			{
 67				_negativeButton->sendEvent(isPressed);
 68				_positiveButton->sendEvent(isReleased);
 69				_pressedBtn = _negativeButton->_id;
 70			}
 71			else
 72			{
 73				_negativeButton->sendEvent(isReleased);
 74				_positiveButton->sendEvent(isPressed);
 75				_pressedBtn = _positiveButton->_id;
 76			}
 77			_leftovers = _leftovers > 0 ? _leftovers - sens : _leftovers + sens;
 78		}
 79		// else do nothing and accumulate leftovers
 80	}
