16	AutoLoad::AutoLoad(CmdRegistry* commandRegistry, bool start)
17	  : PollingThread("AutoLoad thread", bind(&AutoLoad::AutoLoadPoll, this, placeholders::_1), (void*)commandRegistry, 1000, start)
18	{
