21	bool AutoLoad::AutoLoadPoll(void* param)
22	{
23		auto registry = reinterpret_cast<CmdRegistry*>(param);
24		static string lastModuleName;
25		string windowTitle, windowModule;
26		tie(windowModule, windowTitle) = GetActiveWindowName();
27		if (!windowModule.empty() && windowModule != lastModuleName && windowModule.compare("JoyShockMapper.exe") != 0)
28		{
29			lastModuleName = windowModule;
30			string path(AUTOLOAD_FOLDER());
31			auto files = ListDirectory(path);
32			auto noextmodule = windowModule.substr(0, windowModule.find_first_of('.'));
33			COUT_INFO << "[AUTOLOAD] \"" << windowTitle << "\" in focus: "; // looking for config : " , );
34			bool success = false;
35			for (auto file : files)
36			{
37				auto noextconfig = file.substr(0, file.find_first_of('.'));
38				if (iequals(noextconfig, noextmodule))
39				{
40					COUT_INFO << "loading \"AutoLoad\\" << noextconfig << ".txt\".\n";
41					WriteToConsole(path + file);
42					success = true;
43					break;
44				}
45			}
46			if (!success)
47			{
48				COUT_INFO << "create ";
49				COUT << "AutoLoad\\" << noextmodule << ".txt";
50				COUT_INFO << " to autoload for this application.\n";
51			}
52		}
53		return true;
54	}
55	
56	} // namespace JSM
