 10	
 11	// This class handles any kind of assignment command by binding to a JSM variable
 12	// of the parameterized type T. If T is not a base type, implement the following
 13	// functions to reuse the defaultParser:
 14	// static istream &operator >>(istream & input, T &foobar) { ... }
 15	// static ostream &operator <<(ostream & output, T foobar) { ... }
 16	template<typename T>
 17	class JSMAssignment : public JSMCommand
 18	{
 19	protected:
 20		// The display name is usually the same as the name, but in some cases it might be different.
 21		// For example the two GYRO_SENS assignment commands will display MIN_GYRO_SENS and MAX_GYRO_SENS respectively.
 22		const string _displayName;
 23	
 24		// Reference to an existing variable. Make sure the variable's lifetime is longer than
 25		// the command objects
 26		JSMVariable<T>& _var;
 27	
 28		virtual bool parseData(string_view arguments, string_view label) override
 29		{
 30			smatch results;
 31			_ASSERT_EXPR(_parse, L"There is no function defined to parse this command.");
 32			const string argStr(arguments);
 33			if (arguments.empty())
 34			{
 35				displayCurrentValue();
 36			}
 37			else if (arguments.compare(0, 4, "HELP") == 0 && !_help.empty())
 38			{
 39				// Show help.
 40				COUT << _help << '\n';
 41			}
 42			else if (regex_match(argStr, results, regex(R"(\s*=\s*(.*))")))
 43			{
 44				string assignment(results.empty() ? arguments : results[1].str());
 45				if (assignment.rfind("DEFAULT", 0) == 0)
 46				{
 47					_var.reset();
 48				}
 49				else if (!_parse(this, assignment, label))
 50				{
 51					CERR << "Error assigning ";
 52					COUT_INFO << assignment;
 53					CERR << " to " << _displayName << '\n';
 54					CERR << "See ";
 55					COUT_INFO << "HELP";
 56					CERR << " and ";
 57					COUT_INFO << "README";
 58					CERR << " commands for further details.\n";
 59				}
 60			}
 61			else if (!_help.empty())
 62			{
 63				// Parsing has failed.
 64				CERR << "Error when processing the assignment. See the ";
 65				COUT_INFO << "README";
 66				CERR << " for details on valid assignment values\n";
 67			}
 68			return true; // Command is completely processed
 69		}
 70	
 71		static bool modeshiftParser(ButtonID modeshift, JSMSetting<T>* setting, JSMCommand::ParseDelegate* parser, JSMCommand* cmd, string_view argument, string_view label)
 72		{
 73			if (setting && argument.compare("NONE") == 0)
 74			{
 75				setting->markModeshiftForRemoval(modeshift);
 76				COUT << "Modeshift " << modeshift << "," << cmd->_name << " has been removed.\n";
 77				return true;
 78			}
 79			return (*parser)(cmd, argument, label);
 80		}
 81	
 82		// The default parser uses the overloaded >> operator to parse
 83		// any base type. Custom types can also be extracted if you define
 84		// a static parse operation for it.
 85		static bool defaultParser(JSMCommand* cmd, string_view data, string_view label)
 86		{
 87			auto inst = dynamic_cast<JSMAssignment<T>*>(cmd);
 88	
 89			stringstream ss(data.data());
 90			// Read the value
 91			T value(inst->readValue(ss));
 92			if (!ss.fail())
 93			{
 94				T oldVal = inst->_var;
 95				inst->_var.set(value);
 96				inst->_var.updateLabel(label);
 97	
 98				// The assignment won't trigger my listener displayNewValue if
 99				// the new value after filtering is the same as the old.
100				if (oldVal == inst->_var.value())
101				{
102					// So I want to do it myself.
103					inst->displayNewValue(inst->_var);
104				}
105	
106				// Command succeeded if the value requested was the current one
107				// or if the new value is different from the old.
108				return value == oldVal || inst->_var.value() != oldVal; // Command processed successfully
109			}
110			// Couldn't read the value
111			return false;
112		}
113	
114		virtual void displayNewValue(const T& newValue)
115		{
116			// See Specialization for T=Mapping at the end of this file
117			COUT << _displayName << " has been set to " << newValue << '\n';
118		}
119	
120		virtual void displayCurrentValue()
121		{
122			COUT << _displayName << " = " << _var.value() << '\n';
123		}
124	
125		virtual T readValue(stringstream& in)
126		{
127			// Default value reader
128			T value = T();
129			in >> value;
130			return value;
131		}
132	
133		virtual unique_ptr<JSMCommand> getModifiedCmd(char op, string_view chord) override
134		{
135			stringstream ss(chord.data());
136			ButtonID btn;
137			ss >> btn;
138			if (btn > ButtonID::NONE)
139			{
140				stringstream name;
141				name << chord << op << _displayName;
142				if (op == ',')
143				{
144					auto settingVar = dynamic_cast<JSMSetting<T>*>(&_var);
145					if (settingVar)
146					{
147						//Create Modeshift
148						auto chordAssignment = make_unique<JSMAssignment<T>>(name.str(), *settingVar->atChord(btn));
149						chordAssignment->setHelp(_help)->setParser(bind(&JSMAssignment<T>::modeshiftParser, btn, settingVar, &_parse, placeholders::_1, placeholders::_2, placeholders::_3))
150							->setTaskOnDestruction(bind(&JSMSetting<T>::processModeshiftRemoval, settingVar, btn));
151						return chordAssignment;
152					}
153					auto buttonVar = dynamic_cast<JSMButton*>(&_var);
154					if (buttonVar && btn > ButtonID::NONE)
155					{
156						auto chordedVar = buttonVar->atChord(btn);
157						// The reinterpret_cast is required for compilation, but settings will never run this code anyway.
158						auto chordAssignment = make_unique<JSMAssignment<T>>(name.str(), reinterpret_cast<JSMVariable<T>&>(*chordedVar));
159						chordAssignment->setHelp(_help)->setParser(_parse)->setTaskOnDestruction(bind(&JSMButton::processChordRemoval, buttonVar, btn, chordedVar));
160						// BE ADVISED! If a custom parser was set using bind(), the very same bound vars will
161						// be passed along.
162						return chordAssignment;
163					}
164				}
165				else if (op == '+')
166				{
167					auto buttonVar = dynamic_cast<JSMButton*>(&_var);
168					if (buttonVar && btn > ButtonID::NONE)
169					{
170						auto simPressVar = buttonVar->atSimPress(btn);
171						auto simAssignment = make_unique<JSMAssignment<Mapping>>(name.str(), *simPressVar);
172						simAssignment->setHelp(_help)->setParser(_parse)->setTaskOnDestruction(bind(&JSMButton::processSimPressRemoval, buttonVar, btn, simPressVar));
173						// BE ADVISED! If a custom parser was set using bind(), the very same bound vars will
174						// be passed along.
175						return simAssignment;
176					}
177				}
178				else if (op == '*')
179				{
180					auto buttonVar = dynamic_cast<JSMButton*>(&_var);
181					if (buttonVar && btn > ButtonID::NONE)
182					{
183						auto diagPressVar = buttonVar->atDiagPress(btn);
184						auto diagAssignment = make_unique<JSMAssignment<Mapping>>(name.str(), *diagPressVar);
185						diagAssignment->setHelp(_help)->setParser(_parse)->setTaskOnDestruction(bind(&JSMButton::processDiagPressRemoval, buttonVar, btn, diagPressVar));
186						// BE ADVISED! If a custom parser was set using bind(), the very same bound vars will
187						// be passed along.
188						return diagAssignment;
189					}
190				}
191			}
192			return JSMCommand::getModifiedCmd(op, chord);
193		}
194	
195		unsigned int _listenerId;
196	
197	public:
198		JSMAssignment(string_view name, string_view displayName, JSMVariable<T>& var, bool inNoListener = false)
199		  : JSMCommand(name)
200		  , _var(var)
201		  , _displayName(displayName)
202		  , _listenerId(0)
203		{
204			// Child Classes assign their own parser. Use bind to convert instance function call
205			// into a static function call.
206			using namespace placeholders;
207			setParser(bind(&JSMAssignment::defaultParser, _1, _2, _3));
208			if (!inNoListener)
209			{
210				_listenerId = _var.addOnChangeListener(bind(&JSMAssignment::displayNewValue, this, placeholders::_1));
211			}
212		}
213	
214		JSMAssignment(string_view name, JSMVariable<T>& var, bool inNoListener = false)
215		  : JSMAssignment(name, name, var, inNoListener)
216		{
217		}
218	
219		JSMAssignment(JSMSetting<T>& var, bool inNoListener = false)
220		  : JSMAssignment(magic_enum::enum_name(var._id).data(), var, inNoListener)

